'use strict';

var STATUS_LABELS = {todo: 'To do', cooking: 'Cooking', done: 'Done'};
var NEXT_LABELS = {todo: 'Start cooking', cooking: 'Mark done'};
var menu = [];
var quantities = {};
var currentTab = 'order';

function money(cents) {
  return '$' + (cents / 100).toFixed(2);
}

function el(tag, cls, text) {
  var e = document.createElement(tag);
  if (cls) { e.className = cls; }
  if (text !== undefined) { e.textContent = text; }
  return e;
}

function byId(id) {
  return document.getElementById(id);
}

function api(path, options) {
  return fetch('api/' + path, options).then(function (r) {
    return r.json().catch(function () { return {}; }).then(function (data) {
      if (!r.ok) {
        throw new Error(data.error || ('Request failed (' + r.status + ')'));
      }
      return data;
    });
  });
}

function setMessage(id, text, isError) {
  var m = byId(id);
  m.textContent = text || '';
  m.className = 'message' + (text ? (isError ? ' error' : ' ok') : '');
}

/* ---------- Order tab ---------- */

function orderTotal() {
  var total = 0;
  menu.forEach(function (item) {
    total += item.price_cents * (quantities[item.id] || 0);
  });
  return total;
}

function updateTotal() {
  byId('total').textContent = money(orderTotal());
}

function changeQty(id, delta) {
  var q = (quantities[id] || 0) + delta;
  if (q < 0) { q = 0; }
  if (q > 99) { q = 99; }
  quantities[id] = q;
  var span = byId('qty-' + id);
  if (span) { span.textContent = String(q); }
  var card = byId('card-' + id);
  if (card) { card.className = 'card' + (q > 0 ? ' selected' : ''); }
  updateTotal();
}

function renderMenu() {
  var box = byId('menu');
  box.textContent = '';
  menu.forEach(function (item) {
    var card = el('div', 'card');
    card.id = 'card-' + item.id;
    card.appendChild(el('div', 'card-name', item.name));
    card.appendChild(el('div', 'card-price', money(item.price_cents)));
    var controls = el('div', 'qty');
    var minus = el('button', 'qty-btn', '-');
    minus.type = 'button';
    minus.setAttribute('aria-label', 'Remove one ' + item.name);
    minus.addEventListener('click', function () { changeQty(item.id, -1); });
    var count = el('span', 'qty-count', '0');
    count.id = 'qty-' + item.id;
    var plus = el('button', 'qty-btn', '+');
    plus.type = 'button';
    plus.setAttribute('aria-label', 'Add one ' + item.name);
    plus.addEventListener('click', function () { changeQty(item.id, 1); });
    controls.appendChild(minus);
    controls.appendChild(count);
    controls.appendChild(plus);
    card.appendChild(controls);
    box.appendChild(card);
  });
  updateTotal();
}

function loadMenu() {
  return api('menu').then(function (data) {
    menu = data.menu || [];
    menu.forEach(function (item) {
      if (quantities[item.id] === undefined) { quantities[item.id] = 0; }
    });
    renderMenu();
  }).catch(function (err) {
    setMessage('order-message', 'Could not load the menu: ' + err.message, true);
  });
}

function submitOrder() {
  var table = byId('table').value.trim();
  var items = [];
  menu.forEach(function (item) {
    var q = quantities[item.id] || 0;
    if (q > 0) { items.push({id: item.id, quantity: q}); }
  });
  if (!table) {
    setMessage('order-message', 'Please enter a table number.', true);
    return;
  }
  if (items.length === 0) {
    setMessage('order-message', 'Please choose at least one item.', true);
    return;
  }
  var btn = byId('submit');
  btn.disabled = true;
  api('orders', {
    method: 'POST',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({table: table, items: items})
  }).then(function (data) {
    var order = data.order;
    menu.forEach(function (item) { quantities[item.id] = 0; });
    renderMenu();
    byId('table').value = '';
    setMessage('order-message', 'Order #' + order.id + ' for table ' + order.table + ' sent. Total: ' + money(order.total_cents) + '.', false);
  }).catch(function (err) {
    setMessage('order-message', err.message, true);
  }).then(function () {
    btn.disabled = false;
  });
}

/* ---------- Kitchen tab ---------- */

function advanceOrder(id) {
  api('orders/' + id + '/status', {
    method: 'PATCH',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({})
  }).then(function () {
    setMessage('kitchen-message', '', false);
    loadOrders();
  }).catch(function (err) {
    setMessage('kitchen-message', err.message, true);
    loadOrders();
  });
}

function renderOrders(orders) {
  var box = byId('orders');
  box.textContent = '';
  var filter = byId('filter').value;
  var shown = orders.filter(function (o) { return !filter || o.status === filter; });
  if (shown.length === 0) {
    box.appendChild(el('p', 'empty', 'No orders to show.'));
    return;
  }
  shown.forEach(function (o) {
    var card = el('div', 'order status-' + o.status);
    var head = el('div', 'order-head');
    head.appendChild(el('span', 'order-title', 'Order #' + o.id + ' - Table ' + o.table));
    head.appendChild(el('span', 'badge badge-' + o.status, STATUS_LABELS[o.status] || o.status));
    card.appendChild(head);
    card.appendChild(el('div', 'order-time', 'Placed at ' + String(o.created_at).slice(11, 16)));
    var list = el('ul', 'order-items');
    o.items.forEach(function (it) {
      list.appendChild(el('li', '', it.quantity + ' x ' + it.name));
    });
    card.appendChild(list);
    var foot = el('div', 'order-foot');
    foot.appendChild(el('span', 'order-total', money(o.total_cents)));
    if (NEXT_LABELS[o.status]) {
      var btn = el('button', 'primary', NEXT_LABELS[o.status]);
      btn.type = 'button';
      btn.addEventListener('click', function () { advanceOrder(o.id); });
      foot.appendChild(btn);
    }
    card.appendChild(foot);
    box.appendChild(card);
  });
}

var lastOrders = [];

function loadOrders() {
  return api('orders').then(function (data) {
    lastOrders = data.orders || [];
    renderOrders(lastOrders);
  }).catch(function (err) {
    setMessage('kitchen-message', 'Could not load orders: ' + err.message, true);
  });
}

/* ---------- Sales tab ---------- */

function loadSales() {
  return api('sales/today').then(function (data) {
    byId('sales-count').textContent = String(data.order_count);
    byId('sales-total').textContent = money(data.total_cents);
    setMessage('sales-message', '', false);
  }).catch(function (err) {
    setMessage('sales-message', 'Could not load sales: ' + err.message, true);
  });
}

/* ---------- Tabs ---------- */

function refreshCurrent() {
  if (currentTab === 'kitchen') { loadOrders(); }
  else if (currentTab === 'sales') { loadSales(); }
}

function showTab(name) {
  currentTab = name;
  var tabs = document.querySelectorAll('.tab');
  for (var i = 0; i < tabs.length; i++) {
    var active = tabs[i].getAttribute('data-tab') === name;
    tabs[i].className = 'tab' + (active ? ' active' : '');
  }
  ['order', 'kitchen', 'sales'].forEach(function (n) {
    byId('panel-' + n).className = 'panel' + (n === name ? '' : ' hidden');
  });
  refreshCurrent();
}

document.addEventListener('DOMContentLoaded', function () {
  var tabs = document.querySelectorAll('.tab');
  for (var i = 0; i < tabs.length; i++) {
    (function (btn) {
      btn.addEventListener('click', function () { showTab(btn.getAttribute('data-tab')); });
    })(tabs[i]);
  }
  byId('submit').addEventListener('click', submitOrder);
  byId('refresh').addEventListener('click', loadOrders);
  byId('filter').addEventListener('change', function () { renderOrders(lastOrders); });
  loadMenu();
  setInterval(refreshCurrent, 5000);
});

